from taf.gnb.oam.coam.vdu.services.agent.http_client import Agentv1HttpClient
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh


@auto_token_refresh()
class Agentv1:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        self.local_client = Agentv1HttpClient(base_url=con_details.base_url,
                                              connection_alias=con_details.alias)

    def reset_rannic(self, rannic_r_dn, timeout=30, **kwargs):
        return self.local_client.reset_rannic(rannic_r_dn=rannic_r_dn, timeout=timeout, **kwargs)

    def get_rnic_rest_operation(self, operation_id, timeout=30):
        return self.local_client.get_ranic_reset_operation_status(operation_id=operation_id, timeout=timeout)

    def delete_rnic_rest_operation(self, operation_id, timeout=30):
        self.local_client.delete_ranic_reset_operation(operation_id=operation_id, timeout=timeout)

    def get_pod_sync_status(self, pod_id, timeout=30):
        return self.local_client.get_pod_sync_status(pod_id=pod_id, timeout=timeout)

    def reset_vdu(self, timeout, **kwargs):
        return self.local_client.reset_vdu(timeout=timeout, **kwargs)

    def get_reset_vdu_operation_status(self, operation_id, timeout):
        return self.local_client.get_reset_vdu_operation_status(operation_id=operation_id, timeout=timeout)
